}

func string2Style(r row) lipgloss.Style {
	if r.State == "exited" {
		return lipgloss.NewStyle().Foreground(theme.ColorError)
	}
	return lipgloss.NewStyle().Foreground(theme.ColorSuccess)
}

func colouredTable(t *testing.T) Model[row] {
